solutions.naive:
class Solution:
    def maxSatisfied(self, customers: list[int], grumpy: list[int], minutes: int) -> int:
        n = len(customers)
        best = 0
        for start in range(n - minutes + 1):
            total = 0
            end = start + minutes
            for i in range(n):
                if grumpy[i] == 0 or start <= i < end:
                    total += customers[i]
            best = max(best, total)
        return best

solutions.better:
class Solution:
    def maxSatisfied(self, customers: list[int], grumpy: list[int], minutes: int) -> int:
        n = len(customers)
        base = 0
        gain_prefix = [0]
        for c, g in zip(customers, grumpy):
            if g == 0:
                base += c
                gain_prefix.append(gain_prefix[-1])
            else:
                gain_prefix.append(gain_prefix[-1] + c)
        best_gain = 0
        for start in range(n - minutes + 1):
            best_gain = max(best_gain, gain_prefix[start + minutes] - gain_prefix[start])
        return base + best_gain

